def show_images(images):
    fig, ax = plt.subplots(figsize=(20, 20))
    ax.set_xticks([]); ax.set_yticks([])
    # Denormalize images from [-1, 1] to [0, 1]
    images = (images + 1) / 2
    ax.imshow(make_grid(images.detach(), nrow=22).permute(1, 2, 0).clip(0, 1))

def show_batch(dl):
    for images, _ in dl:
        show_images(images)
        break
